insert into public.challenges (id, category, title, min_people, hours_min, hours_max, time_bucket, cost, place, points, level, solo)
values
  (1, 'outdoors', '{"en":"Hike a trail none of you have ever done","hy":"Քայլեք մի արահետով, որով ձեզնից ոչ ոք երբեք չի անցել","ru":"Пройдите тропу, по которой никто из вас ещё не ходил"}'::jsonb, 2, 4, 6, 'half', 1, 'out', 30, 'spicy', false),
  (2, 'outdoors', '{"en":"Watch the sunrise from a high point, with breakfast you packed","hy":"Դիմավորեք արևածագը բարձր կետից՝ ձեր հետ բերած նախաճաշով","ru":"Встретьте рассвет на высокой точке с завтраком, который взяли с собой"}'::jsonb, 2, 3, 3, 'short', 1, 'out', 30, 'spicy', false),
  (3, 'outdoors', '{"en":"Picnic somewhere you''ve never sat down before","hy":"Պիկնիկ արեք մի տեղ, որտեղ երբեք չեք նստել","ru":"Устройте пикник там, где вы ещё никогда не сидели"}'::jsonb, 2, 2, 2, 'short', 2, 'out', 15, 'easy', false),
  (4, 'outdoors', '{"en":"Take a day trip to a town you''ve never visited","hy":"Մեկօրյա ուղևորություն արեք մի քաղաք, որտեղ երբեք չեք եղել","ru":"Съездите на день в город, где вы ещё не были"}'::jsonb, 2, 8, 12, 'full', 2, 'out', 40, 'extreme', false),
  (5, 'outdoors', '{"en":"Stargazing night: get out of the city lights, bring blankets","hy":"Աստղերի գիշեր․ դուրս եկեք քաղաքի լույսերից, վերցրեք ծածկոցներ","ru":"Ночь звёзд: уезжайте от городских огней, возьмите пледы"}'::jsonb, 2, 3, 3, 'short', 1, 'out', 25, 'spicy', false),
  (6, 'outdoors', '{"en":"Go swimming in a lake, river, or sea (safely)","hy":"Լողացեք լճում, գետում կամ ծովում (անվտանգ)","ru":"Искупайтесь в озере, реке или море (безопасно)"}'::jsonb, 2, 3, 3, 'short', 1, 'out', 25, 'spicy', false),
  (7, 'outdoors', '{"en":"Rent bikes and ride somewhere new","hy":"Վարձեք հեծանիվներ և գնացեք մի նոր տեղ","ru":"Возьмите велосипеды напрокат и доедьте до нового места"}'::jsonb, 2, 3, 3, 'short', 2, 'out', 20, 'spicy', false),
  (8, 'outdoors', '{"en":"Camp overnight","hy":"Գիշերեք վրանով","ru":"Заночуйте в палатке"}'::jsonb, 3, 12, 24, 'full', 2, 'out', 50, 'extreme', false),
  (9, 'outdoors', '{"en":"Walk across the city from one edge to the other","hy":"Քայլեք քաղաքով մի ծայրից մյուսը","ru":"Пройдите город пешком от одного края до другого"}'::jsonb, 2, 4, 4, 'half', 1, 'out', 25, 'spicy', false),
  (10, 'outdoors', '{"en":"Find and visit an abandoned or forgotten place (legally)","hy":"Գտեք և այցելեք լքված կամ մոռացված մի վայր (օրինական)","ru":"Найдите и посетите заброшенное или забытое место (законно)"}'::jsonb, 2, 3, 3, 'short', 1, 'out', 25, 'spicy', false),
  (11, 'food', '{"en":"Cook a dish from a country none of you has visited","hy":"Պատրաստեք ուտեստ մի երկրից, որտեղ ձեզնից ոչ ոք չի եղել","ru":"Приготовьте блюдо из страны, где никто из вас не был"}'::jsonb, 2, 3, 3, 'short', 2, 'in', 20, 'spicy', false),
  (12, 'food', '{"en":"Eat at a restaurant serving a cuisine you''ve never tried","hy":"Ճաշեք մի ռեստորանում, որի խոհանոցը երբեք չեք փորձել","ru":"Поужинайте в ресторане с кухней, которую вы ещё не пробовали"}'::jsonb, 2, 2, 2, 'short', 2, 'either', 15, 'easy', false),
  (13, 'food', '{"en":"Cook-off: two teams, same ingredients, one judge","hy":"Խոհարարական մրցույթ․ երկու թիմ, նույն մթերքներ, մեկ դատավոր","ru":"Кулинарная битва: две команды, одни продукты, один судья"}'::jsonb, 4, 3, 3, 'short', 2, 'in', 25, 'spicy', false),
  (14, 'food', '{"en":"Make something from scratch you usually buy (bread, pasta, ice cream)","hy":"Զրոյից պատրաստեք մի բան, որը սովորաբար գնում եք (հաց, մակարոն, պաղպաղակ)","ru":"Сделайте с нуля то, что обычно покупаете (хлеб, пасту, мороженое)"}'::jsonb, 1, 3, 3, 'short', 1, 'in', 20, 'spicy', false),
  (15, 'food', '{"en":"Order the one item on the menu nobody would ever pick","hy":"Պատվիրեք մենյուի այն ուտեստը, որը ոչ ոք երբեք չէր ընտրի","ru":"Закажите то блюдо из меню, которое никто бы никогда не выбрал"}'::jsonb, 2, 1, 1, 'quick', 2, 'either', 10, 'easy', false),
  (16, 'food', '{"en":"Market run: each person buys an ingredient they''ve never used, then cook together","hy":"Շուկա․ ամեն մեկը գնում է մի մթերք, որը երբեք չի օգտագործել, հետո միասին եփում եք","ru":"Поход на рынок: каждый покупает продукт, который никогда не использовал, потом готовите вместе"}'::jsonb, 3, 3, 3, 'short', 2, 'either', 25, 'spicy', false),
  (17, 'food', '{"en":"Blind taste test: 5 versions of the same thing (chocolate, juice, chips)","hy":"Կույր համտես․ նույն բանի 5 տարբերակ (շոկոլադ, հյութ, չիպս)","ru":"Слепая дегустация: 5 версий одного и того же (шоколад, сок, чипсы)"}'::jsonb, 3, 1, 1, 'quick', 1, 'in', 10, 'easy', false),
  (18, 'food', '{"en":"Host a full dinner where every course is a different country","hy":"Կազմակերպեք ընթրիք, որտեղ ամեն ուտեստ տարբեր երկրից է","ru":"Устройте ужин, где каждое блюдо из другой страны"}'::jsonb, 3, 4, 4, 'half', 3, 'in', 35, 'extreme', false),
  (19, 'creative', '{"en":"Make a 2-minute short film together, start to finish, tonight","hy":"Միասին նկարահանեք 2 րոպեանոց կարճամետրաժ ֆիլմ՝ սկզբից մինչև վերջ, այսօր","ru":"Снимите вместе 2-минутный короткий фильм от начала до конца, сегодня"}'::jsonb, 3, 3, 3, 'short', 1, 'either', 30, 'spicy', false),
  (20, 'creative', '{"en":"Paint each other''s portraits (talent not required)","hy":"Նկարեք միմյանց դիմանկարները (տաղանդ պետք չէ)","ru":"Нарисуйте портреты друг друга (талант не нужен)"}'::jsonb, 2, 2, 2, 'short', 1, 'in', 15, 'easy', false),
  (21, 'creative', '{"en":"Write a song together and record it on a phone","hy":"Միասին գրեք երգ և ձայնագրեք այն հեռախոսով","ru":"Напишите вместе песню и запишите её на телефон"}'::jsonb, 3, 2, 2, 'short', 1, 'in', 25, 'spicy', false),
  (22, 'creative', '{"en":"Photo walk: everyone shoots the same theme, then vote on the best","hy":"Ֆոտոզբոսանք․ բոլորը նկարում են նույն թեման, հետո ընտրում եք լավագույնը","ru":"Фотопрогулка: все снимают одну тему, потом голосуете за лучший кадр"}'::jsonb, 2, 2, 2, 'short', 1, 'out', 15, 'easy', false),
  (23, 'creative', '{"en":"Build the tallest tower you can from one material","hy":"Կառուցեք ամենաբարձր աշտարակը մեկ նյութից","ru":"Постройте самую высокую башню из одного материала"}'::jsonb, 3, 1, 1, 'quick', 1, 'in', 10, 'easy', false),
  (24, 'creative', '{"en":"Take a pottery, dance, or art class none of you has tried","hy":"Գնացեք խեցեգործության, պարի կամ նկարչության դաս, որը ձեզնից ոչ ոք չի փորձել","ru":"Сходите на гончарный, танцевальный или художественный урок, который никто из вас не пробовал"}'::jsonb, 2, 2, 2, 'short', 2, 'in', 25, 'spicy', false),
  (25, 'creative', '{"en":"Make a group comic strip about your usual Friday night","hy":"Միասին նկարեք կոմիքս ձեր սովորական ուրբաթ երեկոյի մասին","ru":"Нарисуйте общий комикс про ваш обычный вечер пятницы"}'::jsonb, 3, 2, 2, 'short', 1, 'in', 15, 'easy', false),
  (26, 'learn', '{"en":"Everyone learns one magic trick, then performs it","hy":"Ամեն մեկը սովորում է մեկ աճպարարություն, հետո ցույց տալիս","ru":"Каждый учит один фокус, а потом показывает его"}'::jsonb, 3, 2, 2, 'short', 1, 'in', 15, 'easy', false),
  (27, 'learn', '{"en":"Each person teaches the group something in 10 minutes","hy":"Ամեն մեկը 10 րոպեում խմբին ինչ-որ բան է սովորեցնում","ru":"Каждый за 10 минут учит группу чему-нибудь"}'::jsonb, 3, 2, 2, 'short', 1, 'in', 20, 'spicy', false),
  (28, 'learn', '{"en":"Learn 20 words in a language none of you speaks, then quiz each other","hy":"Սովորեք 20 բառ մի լեզվով, որը ձեզնից ոչ ոք չգիտի, հետո ստուգեք միմյանց","ru":"Выучите 20 слов на языке, которого никто из вас не знает, и проверьте друг друга"}'::jsonb, 2, 1, 1, 'quick', 1, 'in', 15, 'easy', false),
  (29, 'learn', '{"en":"Visit a museum you''ve never been to","hy":"Այցելեք մի թանգարան, որտեղ երբեք չեք եղել","ru":"Сходите в музей, где вы ещё не были"}'::jsonb, 2, 2, 2, 'short', 2, 'in', 15, 'easy', false),
  (30, 'learn', '{"en":"Go to a public lecture, talk, or open-mic","hy":"Գնացեք հանրային դասախոսության, զրույցի կամ open-mic-ի","ru":"Сходите на открытую лекцию, встречу или открытый микрофон"}'::jsonb, 2, 2, 2, 'short', 1, 'in', 20, 'spicy', false),
  (31, 'learn', '{"en":"Learn to juggle three objects","hy":"Սովորեք ձեռնածություն անել երեք առարկայով","ru":"Научитесь жонглировать тремя предметами"}'::jsonb, 1, 1, 1, 'quick', 1, 'either', 10, 'easy', false),
  (32, 'games', '{"en":"Learn and play a board game none of you knows","hy":"Սովորեք և խաղացեք սեղանի խաղ, որը ձեզնից ոչ ոք չգիտի","ru":"Освойте и сыграйте в настольную игру, которую никто из вас не знает"}'::jsonb, 3, 2, 2, 'short', 2, 'in', 15, 'easy', false),
  (33, 'games', '{"en":"Escape room","hy":"Էսքեյփ-ռում","ru":"Квест-комната"}'::jsonb, 3, 2, 2, 'short', 3, 'in', 25, 'spicy', false),
  (34, 'games', '{"en":"Bowling, karting, or laser tag","hy":"Բոուլինգ, կարտինգ կամ լազերային թեգ","ru":"Боулинг, картинг или лазертаг"}'::jsonb, 3, 2, 2, 'short', 2, 'in', 15, 'easy', false),
  (35, 'games', '{"en":"Organize a scavenger hunt for the others","hy":"Կազմակերպեք գանձի որոնում մյուսների համար","ru":"Устройте для остальных охоту за сокровищами"}'::jsonb, 4, 2, 2, 'short', 1, 'either', 25, 'spicy', false),
  (36, 'games', '{"en":"Trivia night: everyone writes 5 questions about themselves","hy":"Վիկտորինայի երեկո․ ամեն մեկը գրում է 5 հարց իր մասին","ru":"Вечер викторины: каждый пишет 5 вопросов о себе"}'::jsonb, 3, 2, 2, 'short', 1, 'in', 15, 'easy', false),
  (37, 'games', '{"en":"Mini-olympics: 5 silly events, medals included","hy":"Մինի-օլիմպիադա․ 5 հիմար մրցաձև, մեդալներով","ru":"Мини-олимпиада: 5 дурацких дисциплин, с медалями"}'::jsonb, 4, 2, 2, 'short', 1, 'out', 25, 'spicy', false),
  (38, 'games', '{"en":"Play a sport none of you has played before","hy":"Խաղացեք մի սպորտաձև, որը ձեզնից ոչ ոք չի խաղացել","ru":"Сыграйте в спорт, в который никто из вас ещё не играл"}'::jsonb, 4, 2, 2, 'short', 1, 'out', 20, 'spicy', false),
  (39, 'social', '{"en":"Volunteer together for half a day","hy":"Կես օր միասին կամավոր աշխատեք","ru":"Поработайте вместе волонтёрами полдня"}'::jsonb, 2, 4, 4, 'half', 1, 'either', 40, 'extreme', false),
  (40, 'social', '{"en":"Clean up a park, beach, or street, with before/after photos","hy":"Մաքրեք այգի, լողափ կամ փողոց՝ «առաջ/հետո» լուսանկարներով","ru":"Уберите парк, пляж или улицу, с фото до и после"}'::jsonb, 2, 2, 2, 'short', 1, 'out', 30, 'spicy', false),
  (41, 'social', '{"en":"Each person brings someone the group has never met","hy":"Ամեն մեկը բերում է մեկին, ում խումբը երբեք չի հանդիպել","ru":"Каждый приводит человека, которого группа ещё не знает"}'::jsonb, 3, 3, 3, 'short', 1, 'either', 25, 'spicy', false),
  (42, 'social', '{"en":"Call or visit an older relative and ask about their youth","hy":"Զանգեք կամ այցելեք տարեց հարազատի և հարցրեք նրա երիտասարդության մասին","ru":"Позвоните или навестите старшего родственника и расспросите о его молодости"}'::jsonb, 1, 1, 1, 'quick', 1, 'either', 20, 'spicy', false),
  (43, 'social', '{"en":"Go to a local event you''d normally skip (concert, festival, match)","hy":"Գնացեք տեղական միջոցառման, որը սովորաբար բաց կթողնեիք (համերգ, փառատոն, խաղ)","ru":"Сходите на местное событие, которое обычно пропускаете (концерт, фестиваль, матч)"}'::jsonb, 2, 3, 3, 'short', 2, 'either', 20, 'spicy', false),
  (44, 'spicy', '{"en":"Phone-free evening: phones in a box at the door","hy":"Երեկո առանց հեռախոսների․ բոլոր հեռախոսները՝ դռան մոտ տուփի մեջ","ru":"Вечер без телефонов: все телефоны в коробку у двери"}'::jsonb, 3, 3, 3, 'short', 1, 'either', 25, 'spicy', false),
  (45, 'spicy', '{"en":"Swap roles: the quietest person plans and leads the whole evening","hy":"Դերերի փոխանակում․ ամենալուռը պլանավորում և ղեկավարում է ամբողջ երեկոն","ru":"Смена ролей: самый тихий планирует и ведёт весь вечер"}'::jsonb, 3, 3, 3, 'short', 1, 'either', 20, 'spicy', false),
  (46, 'spicy', '{"en":"Say yes to everything for one evening (within reason)","hy":"Մեկ երեկո ասեք «այո» ամեն ինչին (ողջամտության սահմաններում)","ru":"Говорите «да» всему один вечер (в пределах разумного)"}'::jsonb, 2, 3, 3, 'short', 2, 'either', 30, 'spicy', false),
  (47, 'spicy', '{"en":"Karaoke, and everyone sings at least once","hy":"Կարաոկե, և բոլորը գոնե մեկ անգամ երգում են","ru":"Караоке, и каждый поёт хотя бы раз"}'::jsonb, 3, 2, 2, 'short', 2, 'in', 25, 'spicy', false),
  (48, 'spicy', '{"en":"Cold plunge or cold shower challenge","hy":"Սառը ջրի մեջ մտնելու կամ սառը ցնցուղի մարտահրավեր","ru":"Челлендж: холодная купель или ледяной душ"}'::jsonb, 1, 0.5, 0.5, 'quick', 1, 'either', 15, 'easy', false),
  (49, 'spicy', '{"en":"Get on a random bus or train and get off at a stop you''ve never been to","hy":"Նստեք պատահական ավտոբուս կամ գնացք և իջեք մի կանգառում, որտեղ երբեք չեք եղել","ru":"Сядьте в случайный автобус или поезд и выйдите на остановке, где никогда не были"}'::jsonb, 2, 3, 3, 'short', 1, 'out', 30, 'spicy', false),
  (50, 'spicy', '{"en":"Wake up at 5am and go do something","hy":"Արթնացեք առավոտյան 5-ին և գնացեք ինչ-որ բան անելու","ru":"Встаньте в 5 утра и идите что-нибудь делать"}'::jsonb, 2, 3, 3, 'short', 1, 'out', 30, 'spicy', false),
  (51, 'quick', '{"en":"Walk somewhere new instead of sitting at the usual place","hy":"Սովորական տեղում նստելու փոխարեն քայլեք մի նոր տեղ","ru":"Прогуляйтесь куда-нибудь в новое место вместо обычного"}'::jsonb, 2, 1, 1, 'quick', 1, 'out', 5, 'easy', false),
  (52, 'quick', '{"en":"Swap your usual drink or snack for something nobody has tried","hy":"Ձեր սովորական ըմպելիքը կամ խորտիկը փոխեք մի բանով, որը ոչ ոք չի փորձել","ru":"Замените привычный напиток или снек на то, что никто не пробовал"}'::jsonb, 2, 0.5, 0.5, 'quick', 1, 'either', 5, 'easy', false),
